<?php require_once 'config.php';$cart=$_SESSION['cart']??[];$items=[];$total=0;if($cart){$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT * FROM products WHERE id IN ($in)");$st->execute($ids);$items=$st->fetchAll();foreach($items as $p)$total+=$p['price']*$cart[$p['id']];}if($_SERVER['REQUEST_METHOD']==='POST'){foreach($_POST['qty'] as $id=>$q){if((int)$q<1)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=(int)$q;}go('cart.php');}$title='Shopping bag';include 'header.php';?><h1>Your shopping bag</h1><?php if(!$items): ?><div class="panel"><p>Your bag is empty.</p><a class="btn btn-rose" href="shop.php">Shop now</a></div><?php else: ?><form method="post" class="panel"><table class="table"><tr><th>Product</th><th>Price</th><th>Qty</th></tr><?php foreach($items as $p): ?><tr><td><?= h($p['name']) ?></td><td><?= money($p['price']) ?></td><td><input class="form-control" style="width:80px" type="number" name="qty[<?= $p['id'] ?>]" value="<?= $cart[$p['id']] ?>" min="0"></td></tr><?php endforeach; ?></table><p class="price">Subtotal: <?= money($total) ?></p><button class="btn btn-outline-secondary">Update bag</button> <a class="btn btn-rose" href="checkout.php">Checkout</a></form><?php endif; ?><?php include 'footer.php'; ?>
